232	pub fn focusGained(
233	    self: *Exec,
234	    td: *termio.Termio.ThreadData,
235	    focused: bool,
236	) !void {
237	    _ = self;
238	
239	    assert(td.backend == .exec);
240	    const execdata = &td.backend.exec;
241	
242	    // Windows has no termios, so there is nothing to poll.
243	    if (comptime builtin.target.os.tag == .windows) return;
244	
245	    if (!focused) {
246	        // Flag the timer to end on the next iteration. This is
247	        // a lot cheaper than doing full timer cancellation.
248	        execdata.termios_timer_running = false;
249	    } else {
250	        // Always set this to true. There is a race condition if we lose
251	        // focus and regain focus before the termios timer ticks where
252	        // if we don't set this unconditionally the timer will end on
253	        // the next iteration.
254	        execdata.termios_timer_running = true;
255	
256	        // If we're focused, we want to start our termios timer. We
257	        // only do this if it isn't already running. We use the termios
258	        // callback because that'll trigger an immediate state check AND
259	        // start the timer.
260	        if (execdata.termios_timer_c.state() != .active) {
261	            _ = termiosTimer(td, undefined, undefined, {});
262	        }
263	    }
264	}
