107	/// of Posix syscalls. The caller is responsible for detail-oriented handling
108	/// of the returned file handles.
109	const PosixPty = struct {
110	    pub const Error = OpenError || GetModeError || GetSizeError || SetSizeError || ChildPreExecError;
111	
112	    pub const Fd = posix.fd_t;
113	
114	    const c = @import("pty-c");
115	
116	    /// The file descriptors for the master and slave side of the pty.
117	    /// The slave side is never closed automatically by this struct
118	    /// so the caller is responsible for closing it if things
119	    /// go wrong.
120	    master: Fd,
121	    slave: Fd,
122	
123	    /// Buffer for storage of slave tty name so that we don't have to recompute
124	    /// it every time we need it.
125	    tty_name_buf: [std.Io.Dir.max_path_bytes:0]u8 = undefined,
126	    /// The name of slave tty. If `null` it has not yet been computed or
127	    /// may not be available. Should not be accessed directly, but through
128	    /// `self.getProcessInfo(.tty_name)`
129	    tty_name: ?[:0]const u8 = null,
130	
131	    pub const OpenError = error{OpenptyFailed};
132	
133	    /// Open a new PTY with the given initial size.
134	    pub fn open(size: winsize) OpenError!Pty {
135	        // Need to copy so that it becomes non-const.
136	        var sizeCopy = size;
137	
138	        var master_fd: Fd = undefined;
139	        var slave_fd: Fd = undefined;
140	        if (c.openpty(
141	            &master_fd,
142	            &slave_fd,
143	            null,
144	            null,
145	            @ptrCast(&sizeCopy),
146	        ) < 0)
147	            return error.OpenptyFailed;
148	        errdefer {
149	            _ = posix.system.close(master_fd);
150	            _ = posix.system.close(slave_fd);
151	        }
152	
153	        // Set CLOEXEC on the master fd, only the slave fd should be inherited
154	        // by the child process (shell/command).
155	        cloexec: {
156	            const flags = posix.system.fcntl(master_fd, posix.F.GETFD);
157	            if (flags == -1) {
158	                log.warn("error getting flags for master fd err=E{s}", .{@tagName(posix.errno(-1))});
159	                break :cloexec;
160	            }
161	
162	            switch (posix.errno(posix.system.fcntl(
163	                master_fd,
164	                posix.F.SETFD,
165	                flags | posix.FD_CLOEXEC,
166	            ))) {
167	                .SUCCESS => {},
168	                else => |e| log.warn("error setting CLOEXEC on master fd err=E{}", .{e}),
169	            }
170	        }
171	
172	        // Enable UTF-8 mode. I think this is on by default on Linux but it
173	        // is NOT on by default on macOS so we ensure that it is always set.
174	        var attrs: c.termios = undefined;
175	        if (c.tcgetattr(master_fd, &attrs) != 0)
176	            return error.OpenptyFailed;
177	        attrs.c_iflag |= c.IUTF8;
178	        if (c.tcsetattr(master_fd, c.TCSANOW, &attrs) != 0)
179	            return error.OpenptyFailed;
180	
181	        return .{
182	            .master = master_fd,
183	            .slave = slave_fd,
184	            .tty_name_buf = undefined,
185	            .tty_name = null,
186	        };
187	    }
