210	    pub fn getSize(self: Pty) GetSizeError!winsize {
211	        var ws: winsize = undefined;
212	        if (c.ioctl(self.master, c.TIOCGWINSZ, @intFromPtr(&ws)) < 0)
213	            return error.IoctlFailed;
214	
215	        return ws;
216	    }
