305	fn startWindows(self: *Command, arena: Allocator) !void {
306	    const cwd_w = if (self.cwd) |cwd| try std.unicode.utf8ToUtf16LeAllocZ(arena, cwd) else null;
307	
308	    // Pass null for lpApplicationName and put the program as the first
309	    // token of lpCommandLine. This lets CreateProcessW perform the
310	    // standard program search (parent-app dir, CWD, system dirs, PATH)
311	    // and append ".exe" when the name has no extension, which is what
312	    // users expect for bare commands like `wsl ~` or `pwsh.exe`.
313	    // It also preserves the child's argv[0] as written by the caller
314	    // rather than replacing it with the resolved absolute path.
315	    const command_line = if (self.args.len > 0)
316	        try windowsCreateCommandLine(arena, self.args)
317	    else
318	        try windowsCreateCommandLine(arena, &.{self.path});
319	    const command_line_w = try std.unicode.utf8ToUtf16LeAllocZ(arena, command_line);
320	    const env_w = if (self.env) |env_map| try createWindowsEnvBlock(arena, env_map) else null;
321	
322	    const any_null_fd = self.stdin == null or self.stdout == null or self.stderr == null;
323	    const null_fd = if (any_null_fd) null_fd: {
324	        // path = "\Device\Null"
325	        const path = [_]u16{ '\\', 'D', 'e', 'v', 'i', 'c', 'e', '\\', 'N', 'u', 'l', 'l' };
326	        var path_unicode_string: windows.UNICODE_STRING = .init(&path);
327	        var attrs: windows.OBJECT_ATTRIBUTES = .{ .ObjectName = &path_unicode_string };
328	
329	        var fd: windows.HANDLE = undefined;
330	        var io_status: windows.IO_STATUS_BLOCK = undefined; // unused
331	        const result = windows.exp.ntdll.NtCreateFile(
332	            &fd,
333	            .{ .GENERIC = .{ .READ = true }, .STANDARD = .{ .SYNCHRONIZE = true } },
334	            &attrs,
335	            &io_status,
336	            null,
337	            windows.FILE_ATTRIBUTE_NORMAL,
338	            windows.FILE_SHARE_READ,
339	            windows.OPEN_EXISTING,
340	            windows.FILE_NON_DIRECTORY_FILE,
341	            null,
342	            0,
343	        );
344	
345	        if (result != .SUCCESS) {
346	            return windows.unexpectedStatus(result);
347	        }
348	
349	        break :null_fd fd;
350	    } else null;
351	    defer {
352	        if (null_fd) |fd| _ = windows.exp.kernel32.CloseHandle(fd);
353	    }
354	
355	    // TODO: In the case of having FDs instead of pty, need to set up
356	    // attributes such that the child process only inherits these handles,
357	    // then set bInheritsHandles below.
358	
359	    const attribute_list, const stdin, const stdout, const stderr = if (self.pseudo_console) |pseudo_console| b: {
360	        var attribute_list_size: usize = undefined;
361	        _ = windows.exp.kernel32.InitializeProcThreadAttributeList(
362	            null,
363	            1,
364	            0,
365	            &attribute_list_size,
366	        );
367	
368	        const attribute_list_buf = try arena.alloc(u8, attribute_list_size);
369	        if (windows.exp.kernel32.InitializeProcThreadAttributeList(
370	            attribute_list_buf.ptr,
371	            1,
372	            0,
373	            &attribute_list_size,
374	        ) == windows.FALSE) return windows.unexpectedError(windows.GetLastError());
375	
376	        if (windows.exp.kernel32.UpdateProcThreadAttribute(
377	            attribute_list_buf.ptr,
378	            0,
379	            windows.PROC_THREAD_ATTRIBUTE_PSEUDOCONSOLE,
380	            pseudo_console,
381	            @sizeOf(windows.HPCON),
382	            null,
383	            null,
384	        ) == windows.FALSE) return windows.unexpectedError(windows.GetLastError());
385	
386	        break :b .{ attribute_list_buf.ptr, null, null, null };
387	    } else b: {
388	        const stdin = if (self.stdin) |f| f.handle else null_fd.?;
389	        const stdout = if (self.stdout) |f| f.handle else null_fd.?;
390	        const stderr = if (self.stderr) |f| f.handle else null_fd.?;
391	        break :b .{ null, stdin, stdout, stderr };
392	    };
393	
394	    var startup_info_ex = windows.STARTUPINFOEX{
395	        .StartupInfo = .{
396	            .cb = if (attribute_list != null) @sizeOf(windows.STARTUPINFOEX) else @sizeOf(windows.STARTUPINFOW),
397	            .hStdError = stderr,
398	            .hStdOutput = stdout,
399	            .hStdInput = stdin,
400	            .dwFlags = windows.STARTF_USESTDHANDLES,
401	            .lpReserved = null,
402	            .lpDesktop = null,
403	            .lpTitle = null,
404	            .dwX = 0,
405	            .dwY = 0,
406	            .dwXSize = 0,
407	            .dwYSize = 0,
408	            .dwXCountChars = 0,
409	            .dwYCountChars = 0,
410	            .dwFillAttribute = 0,
411	            .wShowWindow = 0,
412	            .cbReserved2 = 0,
413	            .lpReserved2 = null,
414	        },
415	        .lpAttributeList = attribute_list,
416	    };
417	
418	    var flags: windows.DWORD = windows.CREATE_UNICODE_ENVIRONMENT;
419	    if (attribute_list != null) flags |= windows.EXTENDED_STARTUPINFO_PRESENT;
420	
421	    var process_information: windows.PROCESS_INFORMATION = undefined;
422	    if (windows.exp.kernel32.CreateProcessW(
423	        null,
424	        command_line_w.ptr,
425	        null,
426	        null,
427	        windows.TRUE,
428	        flags,
429	        if (env_w) |w| w.ptr else null,
430	        if (cwd_w) |w| w.ptr else null,
431	        @ptrCast(&startup_info_ex.StartupInfo),
432	        &process_information,
433	    ) == windows.FALSE) return windows.unexpectedError(windows.GetLastError());
434	
435	    self.pid = process_information.hProcess;
436	}
