   163	    /// Wait for the process to end asynchronously via libxev. This
   164	    /// can only be called ONCE.
   165	    pub fn waitXev(
   166	        self: *FlatpakHostCommand,
   167	        loop: *xev.Loop,
   168	        completion: *Completion,
   169	        comptime Userdata: type,
   170	        userdata: ?*Userdata,
   171	        comptime cb: *const fn (
   172	            ud: ?*Userdata,
   173	            l: *xev.Loop,
   174	            c: *Completion,
   175	            r: WaitError!u8,
   176	        ) void,
   177	    ) void {
   178	        self.state_mutex.lockUncancelable(global.io());
   179	        defer self.state_mutex.unlock(global.io());
   180	
   181	        completion.* = .{
   182	            .callback = (struct {
   183	                fn callback(
   184	                    ud_: ?*anyopaque,
   185	                    l_inner: *xev.Loop,
   186	                    c_inner: *Completion,
   187	                    r: WaitError!u8,
   188	                ) void {
   189	                    const ud = @as(?*Userdata, if (Userdata == void) null else @ptrCast(@alignCast(ud_)));
   190	                    @call(.always_inline, cb, .{ ud, l_inner, c_inner, r });
   191	                }
   192	            }).callback,
   193	            .userdata = userdata,
   194	            .timer = xev.Timer.init() catch unreachable, // not great, but xev timer can't fail atm
   195	        };
   196	
   197	        switch (self.state) {
   198	            .init => completion.result = Error.FlatpakMustBeStarted,
   199	            .err => completion.result = Error.FlatpakSpawnFail,
   200	            .started => |*v| {
   201	                v.loop_xev = loop;
   202	                v.completion = completion;
   203	                return;
   204	            },
   205	            .exited => |v| {
   206	                completion.result = v.status;
   207	            },
   208	        }
   209	
   210	        completion.timer.?.run(
   211	            loop,
   212	            &completion.c_xev,
   213	            0,
   214	            anyopaque,
   215	            completion.userdata,
   216	            (struct {
   217	                fn callback(
   218	                    ud: ?*anyopaque,
   219	                    l_inner: *xev.Loop,
   220	                    c_inner: *xev.Completion,
   221	                    r: xev.Timer.RunError!void,
   222	                ) xev.CallbackAction {
   223	                    const c_outer: *Completion = @fieldParentPtr("c_xev", c_inner);
   224	                    defer if (c_outer.timer) |*t| t.deinit();
   225	
   226	                    const result = if (r) |_| c_outer.result.? else |err| err;
   227	                    c_outer.callback(ud, l_inner, c_outer, result);
   228	                    return .disarm;
   229	                }
   230	            }).callback,
   231	        );
