   234	    /// Send a signal to the started command. This does nothing if the
   235	    /// command is not in the started state.
   236	    pub fn signal(self: *FlatpakHostCommand, sig: u8, pg: bool) !void {
   237	        const pid = pid: {
   238	            self.state_mutex.lockUncancelable(global.io());
   239	            defer self.state_mutex.unlock(global.io());
   240	            switch (self.state) {
   241	                .started => |v| break :pid v.pid,
   242	                else => return,
   243	            }
   244	        };
   245	
   246	        // Get our bus connection.
   247	        var g_err: ?*gio_c.GError = null;
   248	        defer if (g_err) |ptr| gio_c.g_error_free(ptr);
   249	        const bus = gio_c.g_bus_get_sync(gio_c.G_BUS_TYPE_SESSION, null, &g_err) orelse {
   250	            log.warn("signal error getting bus: {s}", .{g_err.?.*.message});
   251	            return Error.FlatpakSetupFail;
   252	        };
   253	        defer gio_c.g_object_unref(bus);
   254	
   255	        const reply = gio_c.g_dbus_connection_call_sync(
   256	            bus,
   257	            "org.freedesktop.Flatpak",
   258	            "/org/freedesktop/Flatpak/Development",
   259	            "org.freedesktop.Flatpak.Development",
   260	            "HostCommandSignal",
   261	            gio_c.g_variant_new(
   262	                "(uub)",
   263	                pid,
   264	                sig,
   265	                @as(c_int, @intCast(@intFromBool(pg))),
   266	            ),
   267	            gio_c.G_VARIANT_TYPE("()"),
   268	            gio_c.G_DBUS_CALL_FLAGS_NONE,
   269	            gio_c.G_MAXINT,
   270	            null,
   271	            &g_err,
   272	        );
   273	        if (g_err != null) {
   274	            log.warn("signal send error: {s}", .{g_err.?.*.message});
   275	            return;
   276	        }
   277	        defer gio_c.g_variant_unref(reply);
   278	    }
