   280	    fn threadMain(self: *FlatpakHostCommand, alloc: Allocator) void {
   281	        // Create a new thread-local context so that all our sources go
   282	        // to this context and we can run our loop correctly.
   283	        const ctx = gio_c.g_main_context_new();
   284	        defer gio_c.g_main_context_unref(ctx);
   285	        gio_c.g_main_context_push_thread_default(ctx);
   286	        defer gio_c.g_main_context_pop_thread_default(ctx);
   287	
   288	        // Get our loop for the current thread
   289	        const loop = gio_c.g_main_loop_new(ctx, 1).?;
   290	        defer gio_c.g_main_loop_unref(loop);
   291	
   292	        // Get our bus connection. This has to remain active until we exit
   293	        // the thread otherwise our signals won't be called.
   294	        var g_err: ?*gio_c.GError = null;
   295	        defer if (g_err) |ptr| gio_c.g_error_free(ptr);
   296	        const bus = gio_c.g_bus_get_sync(gio_c.G_BUS_TYPE_SESSION, null, &g_err) orelse {
   297	            log.warn("spawn error getting bus: {s}", .{g_err.?.*.message});
   298	            self.updateState(.{ .err = {} });
   299	            return;
   300	        };
   301	        defer gio_c.g_object_unref(bus);
   302	
   303	        // Spawn the command first. This will setup all our IO.
   304	        self.start(alloc, bus, loop) catch |err| {
   305	            log.warn("error starting host command: {}", .{err});
   306	            self.updateState(.{ .err = {} });
   307	            return;
   308	        };
   309	
   310	        // Run the event loop. It quits in the exit callback.
   311	        gio_c.g_main_loop_run(loop);
   312	    }
