 29	pub fn pipe2(flags: std.posix.O) PipeError![2]std.posix.fd_t {
 30	    if (@TypeOf(std.posix.system.pipe2) != void) {
 31	        var fds: [2]std.posix.fd_t = undefined;
 32	        switch (std.posix.errno(std.posix.system.pipe2(&fds, flags))) {
 33	            .SUCCESS => return fds,
 34	            .INVAL => unreachable, // Invalid flags
 35	            .FAULT => unreachable, // Invalid fds pointer
 36	            .NFILE => return error.SystemFdQuotaExceeded,
 37	            .MFILE => return error.ProcessFdQuotaExceeded,
 38	            else => |err| return std.posix.unexpectedErrno(err),
 39	        }
 40	    }
 41	
 42	    const fds: [2]std.posix.fd_t = try pipe();
 43	    errdefer {
 44	        close(fds[0]);
 45	        close(fds[1]);
 46	    }
 47	
 48	    // https://github.com/ziglang/zig/issues/18882
 49	    if (@as(u32, @bitCast(flags)) == 0)
 50	        return fds;
 51	
 52	    // CLOEXEC is special, it's a file descriptor flag and must be set using
 53	    // F.SETFD.
 54	    if (flags.CLOEXEC) {
 55	        for (fds) |fd| {
 56	            switch (std.posix.errno(std.posix.system.fcntl(fd, std.posix.F.SETFD, @as(u32, std.posix.FD_CLOEXEC)))) {
 57	                .SUCCESS => {},
 58	                .INVAL => unreachable, // Invalid flags
 59	                .BADF => unreachable, // Always a race condition
 60	                else => |err| return std.posix.unexpectedErrno(err),
 61	            }
 62	        }
 63	    }
 64	
 65	    const new_flags: u32 = f: {
 66	        var new_flags = flags;
 67	        new_flags.CLOEXEC = false;
 68	        break :f @bitCast(new_flags);
 69	    };
 70	    // Set every other flag affecting the file status using F.SETFL.
 71	    if (new_flags != 0) {
 72	        for (fds) |fd| {
 73	            switch (std.posix.errno(std.posix.system.fcntl(fd, std.posix.F.SETFL, new_flags))) {
 74	                .SUCCESS => {},
 75	                .INVAL => unreachable, // Invalid flags
 76	                .BADF => unreachable, // Always a race condition
 77	                else => |err| return std.posix.unexpectedErrno(err),
 78	            }
 79	        }
 80	    }
 81	
 82	    return fds;
 83	}
